// Independent acceptance cases derived from editorial blueprints and literal
// participant choices. Expected results below are not generated by the evaluator.
const assert=require('node:assert/strict'),fs=require('node:fs'),ts=require('typescript');
require.extensions['.ts']=(m,f)=>m._compile(ts.transpileModule(fs.readFileSync(f,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022,esModuleInterop:true}}).outputText,f);
const {authoredTemplate,authoredTemplates,defaultAuthoredTemplate}=require('../lib/authored-templates.ts');
const {createQuizTemplate}=require('../lib/template-factory.ts');
const {evaluateMarketing,validateMarketing}=require('../lib/marketing.ts');
const {gradeQuizSubmission}=require('../lib/scoring.ts');
const {validateFormReferences,resolvePath}=require('../lib/engine.ts');
const {renameGuidedAnswer,removeGuidedAnswer}=require('../lib/guided-editing.ts');
const {removeOutcome}=require('../lib/outcome-editing.ts');
let groups=0;function test(name,fn){fn();groups++;console.log('PASS independent: '+name);}
const form=id=>authoredTemplate(id,'independent');
const outcome=(f,answers)=>evaluateMarketing(f,answers)?.outcomeId;
test('fixed catalogue contract and legacy independent factory',()=>{
 assert.equal(authoredTemplates.length,18);assert.equal(authoredTemplates.reduce((n,t)=>n+t.questionCount,0),276);
 for(const type of ['personality','product_finder','diagnostic','qualification','knowledge','scorecard']){
  assert.deepEqual(authoredTemplates.filter(t=>t.quizType===type).map(t=>t.questionCount).sort((a,b)=>a-b),[8,8,30]);
  assert.equal(defaultAuthoredTemplate(type,'short').questions.length,8);
 }
 const old=createQuizTemplate('product_finder','legacy-one'),other=createQuizTemplate('product_finder','legacy-two');old.questions[0].options[0].label='Changed';assert.notEqual(old.questions[0].options[0].label,other.questions[0].options[0].label);
});
test('personality mixed evidence, minimum evidence and declared-order ties',()=>{
 const f=form('personality-traveller');
 const mixed={weekend:'weekend-planner',stay:'stay-explorer',meal:'meal-connector','free-day':'free-day-explorer',souvenir:'souvenir-connector',transport:'transport-planner',activity:'activity-explorer',pace:'pace-unsure'};
 assert.equal(outcome(f,mixed),'explorer');
 assert.equal(outcome(f,{...mixed,activity:'activity-unsure'}),'planner');
 assert.equal(outcome(f,{weekend:'weekend-explorer',stay:'stay-unsure'}),undefined);
 const renamed=renameGuidedAnswer(f,'stay','stay-explorer','Renamed accommodation preference');assert.equal(outcome(renamed,mixed),'explorer');
 const removed=removeOutcome(f,'explorer');validateFormReferences(removed);assert.equal(outcome(removed,mixed),'planner');
});
test('hard product requirements override otherwise dominant preferences',()=>{
 const website=form('website-package-30');
 const answers=Object.fromEntries(Array.from({length:30},(_,i)=>{const q='w'+String(i+1).padStart(2,'0');return [q,q+'-a'];}));answers.w16='w16-c';
 assert.equal(outcome(website,answers),'shop');
 const workspace=form('best-workspace-8');assert.equal(outcome(workspace,{s01:'s01-a',s02:'s02-c',s03:'s03-a',s04:'s04-a',s05:'s05-a',s06:'s06-a',s07:'s07-a',s08:'s08-a'}),'private-office');
});
test('coffee context has no hidden preference weights',()=>{
 const f=form('ideal-coffee-8');
 const context={c02:'c02-a',c03:'c03-a',c05:'c05-a',c07:'c07-a',c08:'c08-a'};
 assert.equal(outcome(f,context),undefined);
 assert.equal(outcome(f,{...context,c01:'c01-b',c04:'c04-a',c06:'c06-b'}),'balanced');
 assert.equal(outcome(f,{...context,c01:'c01-a',c04:'c04-a',c06:'c06-a',c03:'c03-c'}),'decaf');
});
test('diagnostic mixed severity and neutral evidence',()=>{
 const f=form('diagnostic-lead-generation');
 const answers={'audience-situation':'gap','audience-evidence':'gap','offer-scope':'gap','offer-cost':'gap','visibility-location':'partial','visibility-info':'partial','visibility-intent':'partial','visibility-route':'partial','visibility-maintenance':'partial','followup-hours':'gap'};
 assert.equal(outcome(f,answers),'clarity');
 const team=form('diagnostic-team');assert.equal(outcome(team,{'team-priority':'gap','team-done':'gap','team-handoff':'gap','team-owner':'gap','team-load':'gap'}),'direction');
 assert.equal(outcome(f,Object.fromEntries(f.questions.map(q=>[q.id,'established']))),undefined);
 assert.equal(outcome(f,Object.fromEntries(f.questions.map(q=>[q.id,'unknown']))),undefined);
});
test('implementation simultaneous constraints, exact decimal bounds and context neutrality',()=>{
 const f=form('implementation-fit-30'),ready={i01:'i01-a',i06:'i06-a',i11:'i11-a',i16:'i16-a',i21:4,i26:6};
 assert.equal(outcome(f,ready),'pilot');assert.equal(outcome(f,{...ready,i21:3.999}),'preparation');assert.equal(outcome(f,{...ready,i26:5.999}),'preparation');
 assert.equal(outcome(f,{...ready,i06:'i06-b',i21:3}),'preparation');assert.equal(outcome(f,{...ready,i06:'i06-b'}),'scoping');
 assert.equal(outcome(f,{...ready,i16:'i16-unknown'}),undefined);assert.equal(outcome(f,{...ready,i21:''}),undefined);
 assert.equal(outcome(f,{...ready,i21:81}),undefined);assert.equal(outcome(f,{...ready,i21:-1}),undefined);
 assert.equal(outcome(f,{...ready,i02:'i02-c',i04:'i04-c',i30:'i30-c'}),'pilot');
 assert.throws(()=>validateMarketing(f,true));for(const o of f.marketing.outcomes)o.ctaUrl='https://example.test/next';validateMarketing(f,true);
});
test('renovation route priority and stable answer references',()=>{
 const f=form('renovation-next-step-8');assert.equal(outcome(f,{r01:'r01-b',r02:'r02-a',r03:0}),'assessment');
 assert.equal(outcome(f,{r01:'r01-a',r02:'r02-a',r03:4}),'brief');assert.equal(outcome(f,{r01:'r01-a',r02:'r02-a',r03:3.99}),'research');
 assert.equal(outcome(f,{r01:'r01-b',r02:'r02-unknown',r03:8}),undefined);
 const deleted=removeGuidedAnswer(f,'r02','r02-a');validateFormReferences(deleted);assert.equal(outcome(deleted,{r01:'r01-b',r02:'r02-a',r03:8}),undefined);
});
test('training distinguishes intermediate time, unknown skills and beginner requirements',()=>{
 const f=form('training-route-8');
 for(const [answers,expected] of [[{t01:'t01-a',t02:1.5,t03:'t03-a'},'orientation'],[{t01:'t01-b',t02:1,t03:'t03-a'},'foundations'],[{t01:'t01-a',t02:2,t03:'t03-a'},'applied'],[{t01:'t01-unknown',t02:3,t03:'t03-a'},undefined],[{t01:'t01-c',t02:.99,t03:'t03-a'},'orientation']])assert.equal(outcome(f,answers),expected);
});
test('scorecard mixed practice, real zeros and unavailable coverage',()=>{
 const f=form('scorecard-onboarding');
 const answers={'onboarding-scope':'not-yet','onboarding-milestone':'consistently','onboarding-promises':'sometimes','onboarding-contact':'usually','onboarding-access':'usually','onboarding-task':'sometimes','onboarding-friction':'consistently','onboarding-next':'not-yet'};
 const result=evaluateMarketing(f,answers);assert.equal(result.overallScore,50);assert.deepEqual(result.categories.map(c=>c.score),[50,50,50,50]);
 assert.equal(evaluateMarketing(f,{...answers,'onboarding-scope':'unknown'}).overallScore,null);
 assert.equal(evaluateMarketing(f,Object.fromEntries(f.questions.map(q=>[q.id,'not-yet']))).overallScore,0);
});
test('long scorecard exact minimum evidence yields a bounded category result',()=>{
 const f=form('scorecard-marketing-health');const r=evaluateMarketing(f,{'mh-audience-trigger':'not-yet','mh-audience-language':'consistently','mh-audience-segment':'sometimes'});
 assert.equal(r.categories.find(c=>c.id==='audience').score,44);assert.equal(r.overallScore,null);
 const short=evaluateMarketing(f,{'mh-audience-trigger':'not-yet','mh-audience-language':'consistently'});assert.equal(short.categories.find(c=>c.id==='audience').score,null);
});
test('knowledge mixed correct, incorrect and unsure answers retain explanations',()=>{
 const f=form('knowledge-coffee-basics');const r=gradeQuizSubmission(f,{espresso:'espresso-correct',storage:'storage-correct',grinding:'grinding-correct','cold-brew':'cold-brew-correct',press:'press-correct',decaf:'decaf-alternative-1',latte:'latte-unsure',beans:'beans-alternative-2'});
 assert.equal(r.totalPointsEarned,5);assert.equal(r.totalPointsPossible,8);assert.equal(r.percentageScore,63);assert.equal(r.matchedTier.id,'developing');assert.equal(r.passed,false);
 assert.ok(r.grading.every(q=>q.explanation?.trim()));
});
test('all authored full paths, immutable design changes and no source contamination',()=>{
 for(const t of authoredTemplates){const f=form(t.id),before=JSON.stringify(f);const other=createQuizTemplate(t.id,'other');other.theme.primaryColor='#000000';other.questions[0].title='Changed';assert.equal(JSON.stringify(f),before);assert.equal(form(t.id).questions[0].title,f.questions[0].title);assert.equal(resolvePath(f,{}).questions.length,t.questionCount);assert.equal(f.publishedAt,undefined);validateFormReferences(f);}
});
console.log(`${groups} independent authored-template acceptance groups passed.`);
